import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Method,
	Prop,
	State,
	h,
} from "@stencil/core";

type DropIndicatorEdge = "left" | "top" | "right" | "bottom";

// Shared drag data contract (exported for external reuse)
export type DragData = {
	id: string;
	data?: string;
	operation?: string;
	originalIndex?: number;
};

export type IndicatorEdge = DropIndicatorEdge;

export type DragOverDetail = {
	dragElement: HTMLElement | null;
	targetElement: HTMLElement | null;
	pointer?: { x: number; y: number } | null;
	targetEntry?: { element: HTMLElement; rect: DOMRect } | null;
	indicator?: IndicatorEdge | null;
	event: DragEvent;
};

export type ItemDroppedDetail = {
	dragData?: DragData;
	dragElement: HTMLElement | null;
	targetElement: EventTarget | null;
	indicator?: IndicatorEdge | null;
	event: DragEvent;
};

/**
 * @since 2.18.34
 * @status beta
 *
 * @description The `hbr-drop-zone` component provides a comprehensive drop zone for drag-and-drop operations. It supports copy, move, reorder operations and insertion between elements.
 *
 * @slot - Used to pass in the content for the drop zone.
 **/

@Component({
	tag: "hbr-drop-zone",
	styleUrl: "drop-zone.scss",
	shadow: true,
})
export class DropZone {
	@Element() host: HTMLElement;

	@State() isDragOver = false;
	@State() rowIndicator: { top?: number; bottom?: number } | null = null;

	private ghostElement?: HTMLHbrDragGhostElement;
	private dragSourceElement?: HTMLHbrDraggableElement;
	private dragStartListenerAdded = false;
	private currentTargetElement?: HTMLElement;
	private currentIndicatorClass?: string;
	private currentIndicatorEdge?: IndicatorEdge | null;

	connectedCallback() {
		// Always add dragstart listener for containment tracking
		if (!this.dragStartListenerAdded) {
			document.addEventListener("dragstart", this.handleGlobalDragStart, true);
			// Use bubble phase (false) for dragover so we can override after other handlers
			document.addEventListener("dragover", this.handleGlobalDragOver, false);
			document.addEventListener("dragend", this.handleGlobalDragEnd, true);
			this.dragStartListenerAdded = true;
		}
	}

	/** Text to display in the drop zone when empty */
	@Prop() label = "Drop here";

	/** Whether the drop zone is disabled */
	@Prop() disabled = false;

	/** The orientation of the drop zone, affecting indicator display. */
	@Prop() direction: "vertical" | "horizontal" = "vertical";

	/** Whether drops are restricted to items that originated within this drop zone */
	@Prop({ reflect: true }) contained = false;

	/** Event emitted when an item is dropped */
	@Event({ eventName: "hbr-item-dropped" })
	hbrItemDropped: EventEmitter<ItemDroppedDetail>;

	/** Event emitted when drag starts */
	@Event({ eventName: "hbr-drag-start" })
	hbrDragStart: EventEmitter<DragEvent>;

	/** Event emitted when drag is over the zone */
	@Event({ eventName: "hbr-drag-over" })
	hbrDragOver: EventEmitter<DragOverDetail>;

	/** Event emitted when drag leaves the zone */
	@Event({ eventName: "hbr-drag-leave" })
	hbrDragLeave: EventEmitter<DragEvent>;

	/** Show a row indicator at the given position */
	@Method()
	async showRowIndicator(position: { top?: number; bottom?: number }) {
		this.rowIndicator = position;
	}

	/** Hide the row indicator */
	@Method()
	async hideRowIndicator() {
		this.rowIndicator = null;
	}

	disconnectedCallback() {
		if (this.dragStartListenerAdded) {
			document.removeEventListener(
				"dragstart",
				this.handleGlobalDragStart,
				true,
			);
			document.removeEventListener(
				"dragover",
				this.handleGlobalDragOver,
				false,
			);
			document.removeEventListener("dragend", this.handleGlobalDragEnd, true);
			this.dragStartListenerAdded = false;
		}
	}

	private handleGlobalDragStart = (event: DragEvent) => {
		this.hbrDragStart.emit(event);

		if (!event.target || !(event.target instanceof HTMLElement)) {
			return;
		}

		// Find the draggable element to get its dragId
		const draggableElement = (event.target as HTMLElement).closest(
			"hbr-draggable",
		) as HTMLHbrDraggableElement;
		if (!draggableElement) return;
		const owningDropZone = draggableElement.closest("hbr-drop-zone");
		if (owningDropZone !== this.host) return;
		this.dragSourceElement = draggableElement;

		const dragId = draggableElement?.getAttribute("drag-id") || undefined;

		// Attach ghost as the drag image (if ghost element exists)
		if (this.ghostElement) {
			this.ghostElement.attachToEvent(event, dragId);
		}
	};

	private handleGlobalDragEnd = () => {
		this.isDragOver = false;
		this.rowIndicator = null;
		this.clearIndicatorClasses();
	};

	/**
	 * Clears indicator classes from the current target element
	 */
	private clearIndicatorClasses = () => {
		if (this.currentTargetElement && this.currentIndicatorClass) {
			this.currentTargetElement.classList.remove(this.currentIndicatorClass);
		}
		this.currentTargetElement = undefined;
		this.currentIndicatorClass = undefined;
	};

	/**
	 * Global dragover handler to show indicators and track position
	 */
	private handleGlobalDragOver = (event: DragEvent) => {
		event.preventDefault();

		// Only process if drag originated from this drop zone
		if (!this.dragSourceElement) return;

		const targetElement = (event.target as HTMLElement)?.closest(
			"hbr-draggable",
		) as HTMLElement | null;

		// Check if target is within this drop zone
		if (targetElement) {
			const targetDropZone = targetElement.closest("hbr-drop-zone");
			if (targetDropZone !== this.host) {
				this.clearIndicatorClasses();
				return;
			}
		}

		this.isDragOver = true;

		if (!targetElement) {
			this.clearIndicatorClasses();
			return;
		}

		const targetRect = targetElement.getBoundingClientRect();
		const pointerX = event.clientX;
		const pointerY = event.clientY;

		// Calculate simple indicator edge based on direction
		let indicatorEdge: IndicatorEdge;
		if (this.direction === "horizontal") {
			const centerX = targetRect.left + targetRect.width / 2;
			indicatorEdge = pointerX < centerX ? "left" : "right";
		} else {
			const centerY = targetRect.top + targetRect.height / 2;
			indicatorEdge = pointerY < centerY ? "top" : "bottom";
		}

		const orientationPrefix =
			this.direction === "horizontal" ? "horizontal" : "vertical";
		const positionSuffix =
			indicatorEdge === "top" || indicatorEdge === "left" ? "before" : "after";
		const newIndicatorClass = `hbr-drag-over--${orientationPrefix}-${positionSuffix}`;

		if (
			this.currentTargetElement !== targetElement ||
			this.currentIndicatorClass !== newIndicatorClass
		) {
			this.clearIndicatorClasses();
			targetElement.classList.add(newIndicatorClass);
			this.currentTargetElement = targetElement;
			this.currentIndicatorClass = newIndicatorClass;
		}

		// Store indicatorEdge for use in handleDrop
		this.currentIndicatorEdge = indicatorEdge;

		// Emit drag over event
		const detail: DragOverDetail = {
			dragElement: this.dragSourceElement || null,
			targetElement,
			pointer: { x: pointerX, y: pointerY },
			targetEntry: { element: targetElement, rect: targetRect },
			indicator: indicatorEdge,
			event,
		};
		this.hbrDragOver.emit(detail);
	};

	private getDragData = (event: DragEvent): DragData => {
		const dataTransfer = event.dataTransfer;
		if (!dataTransfer) {
			throw new Error("No data transfer available");
		}

		const id = dataTransfer.getData("text/plain") || "";
		const data = dataTransfer.getData("application/json") || undefined;
		const operation = dataTransfer.dropEffect || "move";

		return {
			id,
			data,
			operation,
		};
	};

	handleGhostSlotChange = (event: Event) => {
		const slot = event.target as HTMLSlotElement;
		const elements = slot.assignedElements();

		if (elements.length > 0) {
			const slottedElement = elements[0] as HTMLElement;
			// It's a drag-ghost component (native drag)
			this.ghostElement = slottedElement as HTMLHbrDragGhostElement;
		} else {
			// Slotted element was removed
			this.ghostElement = undefined;
		}
	};

	handleDragLeave = (event: DragEvent) => {
		const relatedTarget = event.relatedTarget as Node | null;
		if (relatedTarget && this.host.contains(relatedTarget)) return;
		this.isDragOver = false;
		this.clearIndicatorClasses();
		this.hbrDragLeave.emit(event);
	};

	handleDrop = (event: DragEvent) => {
		if (this.disabled) return;

		event.preventDefault();

		const targetElement =
			(event.target as HTMLElement)?.closest("hbr-draggable") || null;
		const indicator = this.currentIndicatorEdge;

		// Reset state
		this.isDragOver = false;
		this.currentIndicatorEdge = null;
		this.clearIndicatorClasses();

		try {
			// Parse drag data from the event
			const dragData = this.getDragData(event);

			// Emit drop event with full context including indicator
			this.hbrItemDropped.emit({
				dragData,
				dragElement: this.dragSourceElement,
				targetElement: targetElement as HTMLElement,
				indicator,
				event,
			});
		} catch (error) {
			console.error("Error handling drop:", error);
			// Emit basic drop event even on error
			this.hbrItemDropped.emit({
				dragElement: this.dragSourceElement,
				targetElement,
				indicator,
				event,
			});
		}
	};

	render() {
		return (
			<Host
				class={{
					"drop-zone": true,
					"drop-zone--drag-over": this.isDragOver,
					"drop-zone--disabled": this.disabled,
					"drop-zone--horizontal": this.direction === "horizontal",
					"drop-zone--vertical": this.direction === "vertical",
				}}
				onDragLeave={this.handleDragLeave}
				onDrop={this.handleDrop}
			>
				<slot name="ghost" onSlotchange={this.handleGhostSlotChange} />
				{this.rowIndicator && (
					<div
						class="drop-zone__row-indicator"
						aria-hidden="true"
						style={{
							left: "0px",
							right: "0px",
							...(this.rowIndicator.top !== undefined
								? { top: `${this.rowIndicator.top}px` }
								: {}),
							...(this.rowIndicator.bottom !== undefined
								? { bottom: `${this.rowIndicator.bottom}px` }
								: {}),
						}}
					>
						<div class="drop-indicator__line" />
						<div class="drop-indicator__marker-dot" />
					</div>
				)}
				<slot />
			</Host>
		);
	}
}
